sys_script_client.script:
function onLoad() {

    for (var x = 0; x < g_form.elements.length; x++) { //MSSRBXSN-1679: To make the empty fields editable with given field message 
        if (g_form.getValue(g_form.elements[x].fieldName) == "") {
            g_form.setReadOnly(g_form.elements[x].fieldName, false);
            g_form.showFieldMsg(g_form.elements[x].fieldName, 'Field can only be updated once post which this will become read-only');
        } else {
            g_form.setReadOnly(g_form.elements[x].fieldName, true);
        }
    }
}
